public class AccessPolicyTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("parse two names", "[READ, WRITE]", AccessPolicy.parse("read,write").toString());
        check("EnumSet normalizes order", "[READ, WRITE]", AccessPolicy.parse("write,read").toString());
        check("parsed set contains ADMIN", true,
                AccessPolicy.parse("admin").contains(AccessPolicy.Permission.ADMIN));
        check("parse all three", 3, AccessPolicy.parse("read,write,admin").size());
        check("empty string parses to empty set", 0, AccessPolicy.parse("").size());
        check("canWrite with WRITE", true, AccessPolicy.canWrite(AccessPolicy.parse("write")));
        check("canWrite with ADMIN only", true, AccessPolicy.canWrite(AccessPolicy.parse("admin")));
        check("read alone cannot write", false, AccessPolicy.canWrite(AccessPolicy.parse("read")));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
