public class AccessPolicy {

    public enum Permission { READ, WRITE, ADMIN }

    public static java.util.Set<Permission> parse(String csv) {
        java.util.Set<Permission> result = java.util.EnumSet.noneOf(Permission.class);
        for (String part : csv.split(",")) {
            String name = part.trim();
            if (!name.isEmpty()) {
                result.add(Permission.valueOf(name.toUpperCase(java.util.Locale.ROOT)));
            }
        }
        return result;
    }

    public static boolean canWrite(java.util.Set<Permission> perms) {
        return perms.contains(Permission.WRITE) || perms.contains(Permission.ADMIN);
    }
}
